DIRS = {0: 'values', 1: 'values-ru', 2: 'values-fa', 3: 'values-zh-rCN'}

def android_escape(text: str) -> str:
    t = escape(text).replace("'", "\\'").replace('"', '\\"')
    if t.startswith('@') or t.startswith('?'):
        t = '\\' + t
    return t

import os
for idx, d in DIRS.items():
    os.makedirs(os.path.join(RES, d), exist_ok=True)
    lines = ['<?xml version="1.0" encoding="utf-8"?>',
             '<!-- MARZ VPN UI strings. Generated from one table so all locales share the same keys. -->',
             '<resources>']
    for key, vals in S.items():
        lines.append(f'    <string name="marz_{key}">{android_escape(vals[idx])}</string>')
    lines.append('</resources>')
    with open(os.path.join(RES, d, 'marz_strings.xml'), 'w', encoding='utf-8') as f:
        f.write('\n'.join(lines) + '\n')
print(len(S), 'keys')
